create or replace view public.buildpulse_accounting_trial_balance with (security_invoker=true) as select j.entity_id,l.account_code,a.name,a.account_type,sum(l.debit) debit,sum(l.credit) credit,sum(l.debit-l.credit) balance from public.buildpulse_journal_lines l join public.buildpulse_ledger_accounts a on a.code=l.account_code join public.buildpulse_journal_entries j on j.id=l.entry_id where j.status='posted' group by j.entity_id,l.account_code,a.name,a.account_type;
create or replace view public.buildpulse_accounting_monthly_summary with (security_invoker=true) as select j.entity_id,date_trunc('month',j.entry_date)::date as period_month,sum(case when a.account_type='income' then l.credit-l.debit else 0 end) as revenue,sum(case when a.account_type='expense' then l.debit-l.credit else 0 end) as expenses,sum(case when l.account_code='2000' then l.credit-l.debit else 0 end) as tax_payable from public.buildpulse_journal_entries j join public.buildpulse_journal_lines l on l.entry_id=j.id join public.buildpulse_ledger_accounts a on a.code=l.account_code where j.status='posted' group by j.entity_id,date_trunc('month',j.entry_date)::date;
create or replace view public.buildpulse_accounting_annual_summary with (security_invoker=true) as select j.entity_id,extract(year from j.entry_date)::int as fiscal_year,sum(case when a.account_type='income' then l.credit-l.debit else 0 end) as revenue,sum(case when a.account_type='expense' then l.debit-l.credit else 0 end) as expenses,sum(case when a.account_type='income' then l.credit-l.debit when a.account_type='expense' then -(l.debit-l.credit) else 0 end) as operating_result from public.buildpulse_journal_entries j join public.buildpulse_journal_lines l on l.entry_id=j.id join public.buildpulse_ledger_accounts a on a.code=l.account_code where j.status='posted' group by j.entity_id,extract(year from j.entry_date)::int;